from decimal import Decimal, InvalidOperation
from collections.abc import Mapping

doc = documents['bc686c9635d419185394ae53e66e0c4a']

# Normalize the imported CSV into record mappings without assuming a single wrapper shape.
def find_records(obj):
    if isinstance(obj, list):
        if all(isinstance(x, Mapping) for x in obj):
            return obj
        raise ValueError('CSV document does not contain mapping rows')
    if isinstance(obj, Mapping):
        for key in ('records', 'rows', 'data'):
            value = obj.get(key)
            if isinstance(value, list) and all(isinstance(x, Mapping) for x in value):
                return value
        if 'label' in obj and 'amount' in obj:
            return [obj]
    raise ValueError(f'Unsupported CSV document shape: {type(obj).__name__}')

records = find_records(doc)
if not records:
    result = [{
        'total': None,
        'average': None,
        'records': 0,
        'maximum': None,
        'validation_status': 'no_valid_records',
        'error_detail': 'CSV contains no data records'
    }]
else:
    required = {'amount'}
    missing = required.difference(records[0].keys())
    if missing:
        result = [{
            'total': None,
            'average': None,
            'records': 0,
            'maximum': None,
            'validation_status': 'schema_error',
            'error_detail': 'missing amount field'
        }]
    else:
        values = []
        errors = []
        for idx, row in enumerate(records, start=1):
            raw = row.get('amount')
            if raw is None or str(raw).strip() == '':
                errors.append({'row': idx, 'reason': 'empty amount', 'raw': raw})
                continue
            try:
                value = Decimal(str(raw).strip())
                if not value.is_finite():
                    raise InvalidOperation('amount is not finite')
                values.append(value)
            except (InvalidOperation, ValueError):
                errors.append({'row': idx, 'reason': 'invalid amount', 'raw': raw})

        if errors:
            result = [{
                'total': None,
                'average': None,
                'records': 0,
                'maximum': None,
                'validation_status': 'validation_error',
                'error_detail': f"{len(errors)} invalid amount(s); first issue at row {errors[0]['row']}: {errors[0]['reason']}"
            }]
        elif not values:
            result = [{
                'total': None,
                'average': None,
                'records': 0,
                'maximum': None,
                'validation_status': 'no_valid_records',
                'error_detail': 'CSV contains no data records'
            }]
        else:
            total = sum(values, Decimal('0'))
            maximum = max(values)
            count = len(values)
            average = total / Decimal(count)
            result = [{
                'total': str(total),
                'average': str(average),
                'records': count,
                'maximum': str(maximum),
                'validation_status': 'ok',
                'error_detail': ''
            }]

